import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaComments, FaClock, FaHeartbeat, FaBrain, FaFire, FaCalendar, FaUser } from 'react-icons/fa';
import Navbar from '../components/Navbar';
import MoodTracker from '../components/MoodTracker';
import HabitCard from '../components/HabitCard';
import StatsCard from '../components/StatsCard';

function Dashboard() {
  const navigate = useNavigate();
  const [userName, setUserName] = useState('');
  const [userAvatar, setUserAvatar] = useState(null);
  const [greeting, setGreeting] = useState('');
  const [selectedMood, setSelectedMood] = useState(null);

  const habits = [
    { id: 1, name: '💧 Drink Water', target: '8 glasses', progress: 6, unit: 'glasses', color: '#4A90E2' },
    { id: 2, name: '🏃 Exercise', target: '30 mins', progress: 30, unit: 'mins', color: '#50E3C2' },
    { id: 3, name: '😴 Sleep', target: '8 hours', progress: 7, unit: 'hours', color: '#9B59B6' },
    { id: 4, name: '📚 Study', target: '2 hours', progress: 1.5, unit: 'hours', color: '#F39C12' },
    { id: 5, name: '🧘 Meditate', target: '10 mins', progress: 10, unit: 'mins', color: '#1ABC9C' },
  ];

  const stats = {
    streak: 12,
    totalFocus: 245,
    habitsCompleted: 18,
    badges: 8
  };

  useEffect(() => {
    const name = localStorage.getItem('userName') || 'Friend';
    const avatar = localStorage.getItem('userAvatar');
    setUserName(name);
    setUserAvatar(avatar);
    
    const hour = new Date().getHours();
    if (hour < 12) setGreeting('🌅 Good Morning');
    else if (hour < 18) setGreeting('☀️ Good Afternoon');
    else setGreeting('🌙 Good Evening');
  }, []);

  const quickActions = [
    { icon: <FaComments size={24} />, label: 'AI Chat', color: '#667eea', path: '/chat', desc: 'Talk to AI' },
    { icon: <FaClock size={24} />, label: 'Focus Timer', color: '#e74c3c', path: '/timer', desc: 'Boost focus' },
    { icon: <FaHeartbeat size={24} />, label: 'Mood Check', color: '#2ecc71', path: '/habits', desc: 'Track mood' },
    { icon: <FaBrain size={24} />, label: 'Insights', color: '#f39c12', path: '/profile', desc: 'View stats' },
  ];

  const inspirationalQuotes = [
    { quote: "You are stronger than you think", author: "MindEase" },
    { quote: "One small step at a time", author: "MindEase" },
    { quote: "Your mental health matters", author: "You" },
    { quote: "Breathe. It's just a bad day, not a bad life", author: "Anonymous" },
  ];

  const randomQuote = inspirationalQuotes[Math.floor(Math.random() * inspirationalQuotes.length)];

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.welcomeCard}>
          <div style={styles.welcomeContent}>
            <div style={styles.userInfoContainer}>
              {/* User Avatar */}
              <div style={styles.avatarContainer}>
                {userAvatar ? (
                  <img src={userAvatar} alt="Avatar" style={styles.userAvatar} />
                ) : (
                  <div style={styles.avatarPlaceholder}>
                    <FaUser size={24} color="#fff" />
                  </div>
                )}
              </div>
              <div>
                <h2 style={styles.greeting}>{greeting}, {userName}! 👋</h2>
                <p style={styles.welcomeText}>Ready to nurture your mental wellness today?</p>
              </div>
            </div>
            <div style={styles.streakBadge}>
              <FaFire color="#e74c3c" size={24} />
              <span style={styles.streakNumber}>{stats.streak}</span>
              <span style={styles.streakText}>day streak</span>
            </div>
          </div>
          
          <div style={styles.quoteBox}>
            <p style={styles.quoteText}>✨ "{randomQuote.quote}"</p>
            <p style={styles.quoteAuthor}>— {randomQuote.author}</p>
          </div>
        </div>

        <div style={styles.statsRow}>
          <StatsCard icon={<FaFire color="#e74c3c" />} value={stats.streak} label="Day Streak" color="#e74c3c" />
          <StatsCard icon={<FaClock color="#3498db" />} value={stats.totalFocus} label="Focus Minutes" color="#3498db" />
          <StatsCard icon={<FaCalendar color="#2ecc71" />} value={stats.habitsCompleted} label="Habits Done" color="#2ecc71" />
          <StatsCard icon={<FaBrain color="#9b59b6" />} value={stats.badges} label="Badges" color="#9b59b6" />
        </div>

        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h3>🎭 How are you feeling right now?</h3>
          </div>
          <MoodTracker selectedMood={selectedMood} setSelectedMood={setSelectedMood} />
        </div>

        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h3>⚡ Quick Actions</h3>
          </div>
          <div style={styles.actionGrid}>
            {quickActions.map((action, index) => (
              <div
                key={index}
                style={{...styles.actionCard, borderTop: `4px solid ${action.color}`}}
                onClick={() => navigate(action.path)}
              >
                <div style={{...styles.actionIcon, background: `${action.color}20`, color: action.color}}>
                  {action.icon}
                </div>
                <h4 style={styles.actionLabel}>{action.label}</h4>
                <p style={styles.actionDesc}>{action.desc}</p>
              </div>
            ))}
          </div>
        </div>

        <div style={styles.section}>
          <div style={styles.sectionHeader}>
            <h3>✅ Today's Habits</h3>
            <button style={styles.viewAll} onClick={() => navigate('/habits')}>Manage →</button>
          </div>
          {habits.map(habit => (
            <HabitCard key={habit.id} habit={habit} />
          ))}
        </div>

        <div style={styles.emergencyBanner}>
          <div>
            <h4>🚨 Need immediate support?</h4>
            <p>You're not alone. Help is available 24/7</p>
          </div>
          <button style={styles.emergencyBtn} onClick={() => navigate('/emergency')}>
            Get Help Now →
          </button>
        </div>
      </div>
    </div>
  );
}

